function normalizePayload(value){
  if(value==null) return {};
  if(typeof value==='string'){
    const trimmed=value.trim();
    if(!trimmed) return {};
    try{return JSON.parse(trimmed);}catch{return {_raw_body:trimmed};}
  }
  if(typeof value==='object') return value;
  return {value};
}
function clean(value){return String(value||'').replace(/\s+/g,' ').trim();}
function stripLegalSuffix(value){
  return clean(value)
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?)\b/gi,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function simplifySearchName(value){
  return clean(stripLegalSuffix(value))
    .replace(/\([^)]*\)/g,' ')
    .replace(/\s*@.*$/,' ')
    .replace(/\b(?:on\s+conference\s+leave|conference\s+leave|temporarily\s+closed|closed\s+temporarily|on\s+leave)\b.*$/i,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function hasCorporatePreference(value){
  return /\b(?:holdings?|group|pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation)\b/i.test(String(value||''));
}
function buildDomainClueQuery(value, preferCorporateRoot){
  const simplified=simplifySearchName(value).toLowerCase();
  const ignored=new Set(['pte','private','ltd','limited','llp','inc','corp','corporation','co','group','holdings','holding']);
  const tokens=simplified.replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter((token)=>token && !ignored.has(token));
  if(tokens.length===2 && tokens[0]==='singapore') return 'sg' + tokens[1] + ' singapore';
  if(preferCorporateRoot && tokens.length>=2 && tokens.length<=4) return tokens.join('') + ' singapore';
  const genericBusiness=new Set(['medical','clinic','clinics','centre','center','health','healthcare','care','family','surgery','practice','services','service']);
  const distinctive=tokens.filter((token)=>!genericBusiness.has(token));
  if(!preferCorporateRoot && tokens.length>=2 && tokens.length<=4 && distinctive.length===1 && distinctive[0].length<=5) return tokens.join('') + ' singapore';
  return '';
}
function buildBrandCoreQuery(value){
  const simplified=simplifySearchName(value);
  const rawTokens=simplified.replace(/[^a-z0-9]+/gi,' ').trim().split(/\s+/).filter(Boolean);
  if(rawTokens.length < 2) return '';
  const ignored=new Set(['pte','private','ltd','limited','llp','inc','corp','corporation','co','group','holdings','holding','clinic','clinics','centre','center','surgery','practice','services','service','medical','healthcare']);
  const kept=rawTokens.filter((token)=>!ignored.has(String(token||'').toLowerCase()));
  if(rawTokens[0] && /^\d+$/.test(rawTokens[0])){
    const brandToken=rawTokens.find((token, index)=>index>0 && /^(?:medical|health|care|insurance|paincare|mission|onecare|wingstop)$/i.test(token));
    if(brandToken) return '"' + [rawTokens[0], brandToken].join(' ') + '" Singapore';
  }
  if(kept.length >= 2) return '"' + kept.slice(0, Math.min(3, kept.length)).join(' ') + '" Singapore';
  return '';
}
const body=normalizePayload(Object.prototype.hasOwnProperty.call($json||{},'body')?$json.body:$json);
const recordId=body.Id || body.id;
if(!body||!recordId) throw new Error('Worker payload missing Id');
const companyName=clean(body.company_name||'');
if(!companyName) throw new Error('Worker payload missing company_name for Id '+recordId);
const preferCorporateRoot=hasCorporatePreference(companyName);
const searchBaseName=stripLegalSuffix(companyName)||companyName;
const corporateSearchName=preferCorporateRoot ? simplifySearchName(stripLegalSuffix(companyName).replace(/\b(?:holdings?|group)\b/gi,' ')) : '';
const searchBackupName=corporateSearchName || simplifySearchName(companyName) || searchBaseName || companyName;
const safeExact=companyName.replace(/"/g,'').trim();
const safeBackup=String(searchBackupName||'').replace(/"/g,'').trim();
const domainClueQuery=buildDomainClueQuery(companyName, preferCorporateRoot);
const brandCoreQuery=buildBrandCoreQuery(companyName);
const broadQuery=safeBackup ? (safeBackup + ' Singapore') : '';
return {json:{
  ...body,
  Id:recordId,
  company_name:companyName,
  prefer_corporate_root:preferCorporateRoot,
  search_exact_query:'"'+safeExact+'" Singapore',
  search_backup_query:safeBackup && safeBackup.toLowerCase()!==safeExact.toLowerCase() ? ('"'+safeBackup+'" Singapore') : '',
  search_broad_query:broadQuery,
  search_domain_query:domainClueQuery,
  search_core_query:brandCoreQuery,
  hia_batch:clean(body.hia_batch)
}};

function hostFromUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1]||'').replace(/^www\./i,'').toLowerCase().trim();
}
function pathFromUrl(value){
  const raw=String(value||'').trim();
  if(!raw)return '/';
  const withProtocol=/^[a-z][a-z0-9+.-]*:\/\//i.test(raw)?raw:'https://'+raw;
  const match=withProtocol.match(/^(?:https?:\/\/)?[^/?#]+([^?#]*)/i);
  return String(match?.[1]||'/').toLowerCase() || '/';
}
function compact(value){
  return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'');
}
function hasLegalEntityMarkers(value){
  return /\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|holdings?|group)\b/i.test(String(value||''));
}
const input=$('Normalize Input').first().json || {};
const payload=$json || {};
const results=Array.isArray(payload.results) ? payload.results : (Array.isArray(payload.organic) ? payload.organic : []);
const generic=new Set(['singapore','limited','ltd','pte','private','company','group','holdings','holding','services','service','the','and']);
const tokens=String(input.company_name || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(t => t.length >= 3 && !generic.has(t));
const companyCompact=compact(input.company_name || '');
const preferCorporateRoot=Boolean(input.prefer_corporate_root) && hasLegalEntityMarkers(input.company_name || '');
const blockedHosts=['baidu.com','facebook.com','instagram.com','linkedin.com','x.com','twitter.com','youtube.com','findglocal.com','tickets.gp','singaporegp.sg','enablingguide.sg','tiktok.com','reddit.com','wikipedia.org','waze.com','streetdirectory.com','findhealthclinics.com','recordowl.com','wherecrowded.sg','asiafirms.com','apabuka.com','threebestrated.sg','doctorxdentist.com','yellowpages.com.sg','neighbourhoodshop.sg','pmc.ncbi.nlm.nih.gov','ncbi.nlm.nih.gov','clinicgeek.com','classpcn.sg','zoominfo.com','jobstreet.com','jobsdb.com','indeed.com','glassdoor.com','crunchbase.com','pitchbook.com','healthcare.com.sg','sgpbusiness.com','bizapore.com','top-rated.online','dividends.sg','sbr.com.sg','sgx.com','links.sgx.com','finance.yahoo.com','yahoo.com','cybo.com','visittiongbahru.com','locallead.ai','companieshouse.sg','medicaltourismchat.com','bebee.com','jooble.org','platomedical.com'];
const blockedHostKeywords=['directory','listing','marketplace','yellowpages','streetdirectory','recordowl','zoominfo','jobstreet','jobsdb','glassdoor','indeed','crunchbase','pitchbook','cybo','apabuka','bizapore','top-rated','ltddir'];
const blockedPathPattern=/(?:\/item\/|\/question\/|\/people\/|\/profile\/|\/company\/|\/listing\/|\/directory\/|\/content\/dam\/)/i;
const blockedExtensionPattern=/\.(?:pdf|docx?|xlsx?|pptx?|txt)$/i;
const listingPattern=/(?:directory|listing|marketplace|map|maps|location|locations|profile|company profile|business profile|business database|registry search|providers?\s+in\s+singapore|yellow pages|book now|reviews?|ratings?|info opening hours|latest information|latest visitor reviews|local businesses|reviews?\s*&\s*profile|jobs?\b|clinic assistant|career)/i;
let strongCount=0;
