for(const row of results.slice(0,10)){
  const title=String(row?.title || '').toLowerCase();
  const snippet=String(row?.snippet || row?.content || '').toLowerCase();
  const url=String(row?.url || row?.link || '').trim();
  const host=hostFromUrl(url);
  const path=pathFromUrl(url);
  const text=[title,snippet,url.toLowerCase()].join(' ');
  const blockedHost=blockedHosts.some(h => host===h || host.endsWith('.'+h)) || blockedHostKeywords.some(k => host.includes(k));
  const blockedDomain=host.endsWith('.gov.sg') || host.endsWith('.edu.sg');
  const blockedPath=blockedPathPattern.test(path);
  const blockedExtension=blockedExtensionPattern.test(path);
  const noisyListing=listingPattern.test(text);
  const utilityBooking=/(?:book appointment|booking)/i.test(title) || /(?:^|\/)book(?:\/|$)/i.test(path) || /^clinic\./i.test(host);
  const rootLabel=String(host||'').replace(/^www\./,'').split('.').filter(Boolean).slice(-2,-1)[0] || String(host||'').replace(/^www\./,'').split('.')[0] || '';
  const rootIdentityHits=tokens.filter(t => compact(rootLabel).includes(compact(t))).length;
  const pathIdentityHits=tokens.filter(t => compact(path).includes(compact(t))).length;
  const tokenHits=tokens.filter(t => text.includes(t)).length;
  const exactTitle=Boolean(companyCompact && compact(title).includes(companyCompact));
  const exactSnippet=Boolean(companyCompact && compact(snippet).includes(companyCompact));
  const identityCarrier = rootIdentityHits >= 1 || pathIdentityHits >= 1;
  const strongResult=(!blockedHost && !blockedDomain && !blockedPath && !blockedExtension && !noisyListing && !utilityBooking) && (exactTitle || ((exactSnippet || tokenHits >= 2) && identityCarrier));
  if(strongResult) strongCount += 1;
  if(exactTitle && !blockedHost && !blockedDomain && !noisyListing && !utilityBooking) legalEntityTitleCount += 1;
  if(blockedHost || blockedDomain || blockedPath || blockedExtension || noisyListing || utilityBooking) noisyCount += 1;
}
const needsCorporateFallback = preferCorporateRoot && strongCount > 0 && legalEntityTitleCount === 0;
const weakSignal = results.length === 0 || strongCount === 0 || needsCorporateFallback;
return { json: { ...payload, use_serper_homepage: weakSignal, searx_result_count: results.length, searx_strong_count: strongCount, searx_noisy_count: noisyCount, searx_legal_entity_title_count: legalEntityTitleCount } };

